<?php require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/pdf_generator.php';checkAuth(['recepcion','admin']);$db=getDBConnection();$date=date('Y-m-d');$s=$db->prepare("SELECT COUNT(*) n,COALESCE(SUM(monto_total_cup),0) total,COALESCE(SUM(CASE WHEN metodo_pago='efectivo' THEN monto_total_cup ELSE 0 END),0) efectivo,COALESCE(SUM(CASE WHEN metodo_pago='transferencia' THEN monto_total_cup ELSE 0 END),0) transfer FROM facturas WHERE tipo='comprobante' AND date(fecha)=?");$s->execute([$date]);$r=$s->fetch();$sales=$db->prepare("SELECT * FROM facturas WHERE tipo='comprobante' AND date(fecha)=? ORDER BY id DESC");$sales->execute([$date]);$rows=$sales->fetchAll();?><div class="card"><h1>Cierre de caja / turno</h1><div class="grid grid-4"><div class="stat">Comprobantes<strong><?=$r['n']?></strong></div><div class="stat">Efectivo<strong><?=money($r['efectivo'])?></strong></div><div class="stat">Transferencias<strong><?=money($r['transfer'])?></strong></div><div class="stat">Total<strong><?=money($r['total'])?></strong></div></div><p class="muted" style="margin-top:16px">El cierre contable definitivo se realiza desde Economía → Caja. Esta vista permite revisar las operaciones del día.</p><div class="table-wrap"><table><tr><th>Número</th><th>Hora</th><th>Mesa</th><th>Pago</th><th>Total</th><th>PDF</th></tr><?php foreach($rows as $x):?><tr><td><?=h($x['numero'])?></td><td><?=h(date('H:i:s',strtotime($x['fecha'])))?></td><td><?=h($x['comanda_id'])?></td><td><?=strtoupper(h($x['metodo_pago']))?></td><td class="gold"><?=money($x['monto_total_cup'])?></td><td><a class="btn olive" href="<?=url('recepcion/imprimir_factura.php?id='.(int)$x['id'])?>">PDF</a></td></tr><?php endforeach;?></table></div></div><?php require_once __DIR__.'/../includes/footer.php';?>
